parameters.functionScript:
var rows = Inputs.rows || [];
var id = String(Inputs.itemId || '');
var dir = String(Inputs.direction || '');
var i = -1;
for (var k = 0; k < rows.length; k++) if (rows[k] && rows[k].id === id) i = k;
if (i < 0) return;
var j = dir === 'up' ? i - 1 : dir === 'down' ? i + 1 : 0;
if (j < 0 || j >= rows.length || j === i) return;
Outputs.firstId = id;
Outputs.from = i + 1;
Outputs.to = j + 1;
if (dir === 'top') {
  // Above whatever is first now. Nobody else's row is rewritten.
  Outputs.firstPosition = Number(rows[0].position) - 1;
  Outputs.hasSecond = false;
} else {
  // Swap with the neighbour.
  Outputs.firstPosition = Number(rows[j].position);
  Outputs.secondId = rows[j].id;
  Outputs.secondPosition = Number(rows[i].position);
  Outputs.hasSecond = true;
}
Outputs.summary = 'Next actions reordered';
Outputs.go();

var DEMO_KEY = "nodegx-todo-list-demo-v1";
function demoLoad() {
  var raw = null;
  try { raw = window.localStorage.getItem(DEMO_KEY); } catch (e) { raw = null; }
  if (raw === null && typeof window.__todoListDemo === 'string') raw = window.__todoListDemo;
  if (raw === null) return null;
  try { return JSON.parse(raw); } catch (e) { return null; }
}
function demoSave(store) {
  var raw = JSON.stringify(store);
  window.__todoListDemo = raw;
  try { window.localStorage.setItem(DEMO_KEY, raw); } catch (e) {}
}
var id = String(Inputs.modelId || '');
var store = demoLoad();
var list = (store && store["Action"]) || [];
var record = null;
for (var i = 0; i < list.length; i++) if (list[i] && list[i].id === id) record = list[i];
if (!record) { Outputs.failure(); return; }
record.position = Inputs.position;
record.updatedAt = new Date().toISOString();
try { demoSave(store); } catch (e) { Outputs.failure(); return; }
Outputs.id = id;
Outputs.done();

